mkdir -p /tmp/chk; cat > /tmp/chk/check.py <<'E'
import sys, math, datetime as dt
import pandas as pd
from zoneinfo import ZoneInfo
week=sys.argv[1]
z=ZoneInfo("America/Chicago")
d=pd.read_csv(f"/app/data/northwind/export_{week}.csv")
d["ts"]=pd.to_datetime(d.interval_start_local.str.slice(0,16)+d.utc_offset, format="%Y-%m-%d %H:%M%z", utc=True).dt.floor("30min")
d=d.drop_duplicates(["queue","ts"],keep="last")
def erlc(a,n):
    s=0;t=1.0
    for k in range(n):
        if k>0:t*=a/k
        s+=t
    t*=a/n
    top=t*n/(n-a)
    return top/(s+top)
def req(v,aht,tg,sec):
    if v<=0:return 0
    a=v/1800*aht
    n=max(1,math.ceil(a))
    while True:
        if n>a:
            sl=1-erlc(a,n)*math.exp(-(n-a)*sec/aht)
            if sl>=tg and a/n<=0.85:return n
        n+=1
T={"priority":(.9,30),"standard":(.8,20),"vip":(.9,20)}
d["req"]=[req(v,h,*T[q]) for v,h,q in zip(d.volume,d.aht_sec,d.queue)]
d=d.set_index(["queue","ts"])
print("intervals",d.index.get_level_values(1).nunique(),"reqhours",d.req.sum()*.5)
s=pd.read_csv("/app/out/northwind/schedule.csv")
for c in ["segment_start_utc","segment_end_utc","break_start_utc"]: s[c]=pd.to_datetime(s[c],utc=True)
ag=pd.read_csv("/app/data/agents/northwind.csv").set_index("agent_id")
hrs=((s.segment_end_utc-s.segment_start_utc).dt.total_seconds()/3600)
print("hours",hrs.sum(),"ratio",hrs.sum()/(d.req.sum()*.5))
grid=sorted(d.index.get_level_values(1).unique())
ops={q:[t for t in grid if (8<=t.astimezone(z).hour<20 if q=="vip" else t.astimezone(z).hour>=6)] for q in T}
gross={q:{t:0 for t in grid} for q in T}; brk={q:{t:0 for t in grid} for q in T}
for r in s.itertuples():
    for t in grid:
        if r.segment_start_utc<=t<r.segment_end_utc:
            gross[r.queue][t]+=1
        if r.break_minutes>0 and r.break_start_utc<=t<r.break_start_utc+pd.Timedelta(minutes=30) and r.segment_start_utc<=t<r.segment_end_utc: brk[r.queue][t]+=1
for q in T:
    m=sum(1 for t in ops[q] if gross[q][t]-brk[q][t]>=d.req.get((q,t),0))
    print(q,len(ops[q]),m/len(ops[q]))
under=sum(max(0,d.req[(q,t)]-(gross[q][t]-brk[q][t])) for q in T for t in grid)*.5
print("under",under)
# rules
viol=[]
s["day"]=s.segment_start_utc.map(lambda t:t.astimezone(z).date())
shifts=s.groupby(["agent_id","day"]).agg(st=("segment_start_utc","min"),en=("segment_end_utc","max"),n=("segment_idx","count"),q=("queue","nunique"),
    hrs=("segment_end_utc",lambda x:0)).reset_index()
for a,g in shifts.groupby("agent_id"):
    g=g.sort_values("st")
    for (_,r1),(_,r2) in zip(g.iterrows(),list(g.iterrows())[1:]):
        if r2.st-r1.en<pd.Timedelta(hours=11): viol.append(("rest",a))
    days=sorted(g.day); run=1
    for x,y in zip(days,days[1:]):
        run=run+1 if (y-x).days==1 else 1
        if run>5: viol.append(("run",a))
    h=hrs[s.agent_id==a].sum()
    cap=40 if ag.contract[a]=="FT" else 24
    if h>cap: viol.append(("cap",a,h))
    sk=set(ag.skills[a].split(";"))
    if not set(s[s.agent_id==a].queue)<=sk: viol.append(("skill",a))
    if (g.n>1).any() and ag.contract[a]!="PT": viol.append(("split",a))
for r in s.itertuples():
    pass
# breaks
for (a,day),g in s.groupby(["agent_id","day"]):
    h=hrs[g.index].sum(); b=g[g.break_minutes>0]
    if (h>=6)!=(len(b)==1) or len(b)>1: viol.append(("breakcount",a,day)); continue
    if len(b)==0: continue
    if b.break_minutes.iloc[0]!=20: viol.append(("bmin",a))
    st=g.segment_start_utc.min(); bs=b.break_start_utc.iloc[0]; q=g.queue.iloc[0]
    if not (pd.Timedelta(hours=2)<=bs-st<=pd.Timedelta(hours=5)): viol.append(("bwin",a,day))
    cands=[t for t in grid if pd.Timedelta(hours=2)<=t-st<=pd.Timedelta(hours=5) and any(x.segment_start_utc<=t<x.segment_end_utc for x in g.itertuples())]
    sur=lambda t:gross[q][t]-d.req.get((q,t),0)
    if sur(bs)<max(sur(t) for t in cands): viol.append(("bsurplus",a,day))
# vip floor
for t in grid:
    l=t.astimezone(z)
    if l.hour>=6 and gross["vip"][t]<1: viol.append(("vipfloor",t))
# overlap
for a,g in s.groupby("agent_id"):
    g=g.sort_values("segment_start_utc")
    if (g.segment_start_utc.values[1:]<g.segment_end_utc.values[:-1]).any(): viol.append(("overlap",a))
# templates not crossing local midnight
for r in s.itertuples():
    if r.segment_start_utc.astimezone(z).date()!=(r.segment_end_utc-pd.Timedelta(seconds=1)).astimezone(z).date(): viol.append(("midnight",r.agent_id))
print("agents",s.agent_id.nunique(),"violations",len(viol),viol[:10])
E
